#include <math.h>
#include <stdint.h>
#include <stddef.h>
#include <string.h>
#include <riscv_vector.h>

void kernel_cos_s8(const int8_t *input, int8_t *output, int n, float scale_in, float scale_out, int activation_min, int activation_max) {
    if (n < 32) {
        for (int i = 0; i < n; i++) {
            const double y = cos((double)input[i] * (double)scale_in);
            int32_t v = (int32_t)round(y / (double)scale_out);
            if (v < activation_min) v = activation_min;
            if (v > activation_max) v = activation_max;
            output[i] = (int8_t)v;
        }
        return;
    }

    uint8_t used[256] = {0};
    int8_t table[256];

    for (int i = 0; i < n; i++) {
        const uint8_t index = (uint8_t)((uint8_t)input[i] ^ UINT8_C(0x80));
        used[index] = 1;
    }

    for (int index = 0; index < 256; index++) {
        if (used[index]) {
            const int x = index - 128;
            const double y = cos((double)x * (double)scale_in);
            int32_t v = (int32_t)round(y / (double)scale_out);
            if (v < activation_min) v = activation_min;
            if (v > activation_max) v = activation_max;
            table[index] = (int8_t)v;
        }
    }

    size_t vl;
    for (int i = 0; i < n; i += (int)vl) {
        vl = __riscv_vsetvl_e8m1((size_t)(n - i));
        vint8m1_t values = __riscv_vle8_v_i8m1(input + i, vl);
        values = __riscv_vxor_vx_i8m1(values, (int8_t)-128, vl);
        vuint8m1_t indices = __riscv_vreinterpret_v_i8m1_u8m1(values);
        vint8m1_t result = __riscv_vluxei8_v_i8m1(table, indices, vl);
        __riscv_vse8_v_i8m1(output + i, result, vl);
    }
}
